import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';

import {
  PublicoAvaliacao,
  VisualizarVotacaoService
} from '../../../../services/visualizar-votacao.service';

@Component({
  selector: 'app-votacao-avaliacao',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './votacao-avaliacao.component.html',
  styleUrls: ['./votacao-avaliacao.component.scss']
})
export class VotacaoAvaliacaoComponent {

  @Input({ required: true })
  votacao!: any;

  @Input()
  publicoAlvo: PublicoAvaliacao = 'PUBLICO';

  @Output()
  votoConcluido = new EventEmitter<void>();

  notas = [1, 2, 3, 4, 5];

  enviando = false;
  votoRegistrado = false;
  erro = '';

  avaliacoes: Record<number, Record<number, number>> = {};
  justificativas: Record<number, Record<number, string>> = {};

  constructor(
    private readonly visualizarVotacaoService: VisualizarVotacaoService
  ) { }

  atribuirNota(
    votacaoCandidatoId: number,
    criterioId: number,
    nota: number
  ): void {
    if (this.votoRegistrado) {
      return;
    }

    if (!this.avaliacoes[votacaoCandidatoId]) {
      this.avaliacoes[votacaoCandidatoId] = {};
    }

    this.avaliacoes[votacaoCandidatoId][criterioId] = nota;
  }

  getNota(
    votacaoCandidatoId: number,
    criterioId: number
  ): number | undefined {
    return this.avaliacoes[votacaoCandidatoId]?.[criterioId];
  }

  atribuirJustificativa(
    votacaoCandidatoId: number,
    criterioId: number,
    justificativa: string
  ): void {
    if (this.votoRegistrado) {
      return;
    }

    if (!this.justificativas[votacaoCandidatoId]) {
      this.justificativas[votacaoCandidatoId] = {};
    }

    this.justificativas[votacaoCandidatoId][criterioId] = justificativa;
  }

  getJustificativa(
    votacaoCandidatoId: number,
    criterioId: number
  ): string {
    return this.justificativas[votacaoCandidatoId]?.[criterioId] ?? '';
  }

  todosPreenchidos(): boolean {
    if (!this.votacao) {
      return false;
    }

    return this.votacao.candidatos.every(
      (candidato: any) =>
        this.votacao.criterios.every((criterio: any) => {
          const notaPreenchida =
            this.avaliacoes[candidato.votacaoCandidatoId]?.[criterio.id] !== undefined;

          if (!notaPreenchida) {
            return false;
          }

          if (this.publicoAlvo === 'AVALIADOR') {
            return this.getJustificativa(
              candidato.votacaoCandidatoId,
              criterio.id
            ).trim().length > 0;
          }

          return true;
        })
    );
  }

  confirmarAvaliacao(): void {
    if (!this.todosPreenchidos() || this.votoRegistrado) {
      return;
    }

    this.enviando = true;
    this.erro = '';

    this.visualizarVotacaoService
      .votar(
        this.votacao.id,
        {
          conselhoId: null,
          itens: this.montarItens()
        },
        this.publicoAlvo
      )
      .subscribe({
        next: () => {
          this.votoRegistrado = true;
          this.enviando = false;
          this.votoConcluido.emit();
        },
        error: (error) => {
          this.erro =
            error?.error?.message ||
            'Erro ao registrar avaliação.';

          this.enviando = false;
        }
      });
  }

  private montarItens(): any[] {
    return this.votacao.candidatos.map((candidato: any) => ({
      votacaoCandidatoId: candidato.votacaoCandidatoId,
      escolhido: false,
      nota: null,
      criterios: this.votacao.criterios.map((criterio: any) => ({
        criterioId: criterio.id,
        nota: this.avaliacoes[candidato.votacaoCandidatoId][criterio.id],
        justificativa: this.publicoAlvo === 'AVALIADOR'
          ? this.getJustificativa(candidato.votacaoCandidatoId, criterio.id).trim()
          : null
      }))
    }));
  }
}
