import { Injectable } from '@angular/core';
import { HttpHeaders } from '@angular/common/http';
import { ApiBaseService } from '../core/api-base.service';
import { Observable } from 'rxjs';

export type PublicoAvaliacao = 'PUBLICO' | 'AVALIADOR';

export interface VotacaoPublica {
  id: number;
  nome: string;
  tipo: string;
  publicoAlvo: PublicoAvaliacao;
  imagemUrl: string;
  dataInicio: string;
  dataFim: string;
  candidatos: VotacaoPublicoCandidato[];
  criterios: CriterioPublico[];
}

export interface VotacaoResumo {
  id: number | string;
  nome: string;
  anoId: string;
  anoDescricao: string;
  categoriaId: number;
  categoriaNome: string;
  imagemUrl: string;
  dataInicio: string;
  dataFim: string;
  dataPublicacao: string;
  createdAt: string;
  tipo: string;
}

export interface VotacaoPublicoCandidato {
  votacaoCandidatoId: number;
  candidatoId: number;
  nome: string;
  nomeProjeto: string;
  imagemUrl: string;
}

export interface CriterioPublico {
  id: number;
  nome: string;
  publicoAlvo: PublicoAvaliacao;
}

export interface LoginVotanteResponse {
  token: string;
  tokenType: string;
  usuario: {
    id: number;
    nomeCompleto: string;
    email: string;
    cpf: string;
    eligibilityId: string;
    codigoVotacao: string;
    createdAt: string;
  };
}

export interface RegistrarVotoPayload {
  conselhoId: number | null;
  itens: Array<{
    votacaoCandidatoId: number;
    escolhido: boolean;
    nota: number | null;
    criterios: Array<{
      criterioId: number;
      nota: number;
      justificativa?: string | null;
    }>;
  }>;
}

@Injectable({ providedIn: 'root' })
export class VisualizarVotacaoService extends ApiBaseService {

  get(id: number, publicoAlvo: PublicoAvaliacao): Observable<VotacaoPublica> {
    return this.http.get<VotacaoPublica>(
      `${this.baseUrl}/voto/${id}/visualizacao/${publicoAlvo}`
    );
  }

  listarVotacoes(): Observable<VotacaoResumo[]> {
    const token = localStorage.getItem('votante_token');

    if (!token) {
      return this.http.get<VotacaoResumo[]>(`${this.baseUrl}/votacoes`);
    }

    return this.http.get<VotacaoResumo[]>(
      `${this.baseUrl}/votacoes`,
      {
        headers: new HttpHeaders({
          Authorization: `Bearer ${token}`
        })
      }
    );
  }

  autenticarVotante(codigo: string): Observable<LoginVotanteResponse> {
    return this.http.post<LoginVotanteResponse>(
      `${this.baseUrl}/auth/votante`,
      { codigo }
    );
  }

  votar(
    votacaoId: number,
    payload: RegistrarVotoPayload,
    publicoAlvo: PublicoAvaliacao = 'PUBLICO'
  ) {
    return this.http.post(
      `${this.baseUrl}/voto/${votacaoId}/votos/${publicoAlvo}`,
      payload
    );
  }
}
